const config = require(\"./config\");
const { connection } = require(\"./queue\");

const RATE_LIMIT_NOTIFICATIONS_PER_SEC = 4; // Conservative: 4 req/sec for 5 req/sec limit
const RATE_LIMIT_KEY = \"rate:notifications\";
const TOKEN_REFILL_INTERVAL_MS = 250; // Refill every 250ms = 1 token

async function acquireToken() {
  const now = Date.now();
  const key = RATE_LIMIT_KEY;

  // Get current state: [count, lastRefill]
  const state = await connection.getex(key);
  const [count, lastRefill] = state ? JSON.parse(state).split(\",\") : [RATE_LIMIT_NOTIFICATIONS_PER_SEC, now];
  const timeSinceRefill = now - lastRefill;
  const tokensToAdd = Math.floor(timeSinceRefill / TOKEN_REFILL_INTERVAL_MS);
  const newCount = Math.min(RATE_LIMIT_NOTIFICATIONS_PER_SEC, parseInt(count) + tokensToAdd);
  const newLastRefill = lastRefill + tokensToAdd * TOKEN_REFILL_INTERVAL_MS;

  if (newCount > 0) {
    // We have tokens, use one
    const newState = "'`${newCount - 1},${newLastRefill}`;
    await connection.set(key, newState, "EX", 60);
    return true;
  }

  // No tokens available, save state and wait
  const newState = `${newCount},${newLastRefill}`;
  await connection.set(key, newState, "EX", 60);
  return false;
}

async function waitForToken() {
  while (!(await acquireToken())) {
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
}

module.exports = { acquireToken, waitForToken };
EOF
